Item.method_code:
const methodName = this.getProperty('name');
let result = aras.applyMethod(methodName, '');
if (result === null || result === false) {
	result = '<Error />';
}

result = formatXml(result);
result = htmlEscape(result);
result = '<PRE>Method name = ' + methodName + '\n<HR />\n' + result + '<HR />\n</PRE>\n';
return result;

function formatXml(xml) {
	let formatted = '';
	const reg = new RegExp('(>)(<)(/*)', 'g');
	xml = xml.replace(reg, '$1\r\n$2$3');
	let pad = 0;
	each(xml.split('\r\n'), function(index, node) {
		let indent = 0;
		if (node.match(/.+<\/\w[^>]*>$/)) {
			indent = 0;
		} else if (node.match(/^<\/\w/)) {
			if (pad !== 0) {
				pad -= 1;
			}
		} else if (node.match(/^<\w[^>]*[^/]>.*$/)) {
			indent = 1;
		} else {
			indent = 0;
		}

		let padding = '';
		for (let i = 0; i < pad; i++) {
			padding += '\t';
		}

		formatted += padding + node + '\r\n';
		pad += indent;
	});

	return formatted;
}

function htmlEscape(str) {
	return str.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function each(object, callback) {
	let name;
	let i = 0;
	const length = object.length;

	if (length === undefined) {
		for (name in object) {
			if (callback.call(object[name], name, object[name]) === false) {
				break;
			}
		}
	} else {
		// eslint-disable-next-line
		for (let value = object[0]; i < length && callback.call(value, i, value) !== false; value = object[++i]) {}
	}

	return object;
}
